/// <summary>
/// The <c>METCBCTInvoicePostingContract</c> class is the data contract class for the
/// <c>METCBCTInvoicePostingService</c> service.
/// </summary>
/// <remarks>
/// This class is the data contract class for the <c>METCBCTInvoicePostingService</c> service.
/// </remarks>
[DataContractAttribute]
[SysOperationContractProcessing(classStr(METCBCTInvoicePostingUIBuilder))]
public class METCBCTInvoicePostingContract implements SysOperationValidatable
{
    str             packedQuery;
    container       cbCtInvoiceHeaderTableList;
    METThreadCount  threadCount;

}

Method.Source:
/// <summary>
/// Gets or sets the value of the datacontract parameter invoice list.
/// </summary>
/// <param name="_cbCtInvoiceHeaderTableList">
/// The new value of the datacontract parameter container of invoice list; optional.
/// </param>
/// <returns>
///  The current value of datacontract parameter invoice list
/// </returns>
[DataMemberAttribute]
public container parmInvoiceList(container _cbCtInvoiceHeaderTableList = cbCtInvoiceHeaderTableList)
{
    cbCtInvoiceHeaderTableList = _cbCtInvoiceHeaderTableList;
    return cbCtInvoiceHeaderTableList;
}

/// <summary>
/// Gets or sets the value of the datacontract parameter query name.
/// </summary>
/// <param name="_packedQuery">
/// The new value of the datacontract parameter query; optional.
/// </param>
/// <returns>
///  The current value of datacontract parameter query
/// </returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METCBCTInvoiceHeaderTableQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

    /// <summary>
    /// Provides thread count parameter
    /// </summary>
    /// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
    /// <returns>The thread count</returns>
    [DataMember, SysOperationControlVisibilityAttribute(true)]
    public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
    {
        threadCount = _threadCount;

        return threadCount;
    }

    /// <summary>
    /// Validate parameters
    /// </summary>
    /// <returns>True if successful; otherwise, false.</returns>
    public boolean validate()
    {
        boolean isValid = true;

        if (!threadCount)
        {
            isValid = checkFailed("@MET:ThreadCountValidate");
        }

        return isValid;
    }
